#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_SECCHI = 64;
constexpr size_t MAX_CHIAVI = 64;

uint64_t hash_fnv1a(const char *s) {
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *p = (const unsigned char *)s; *p != '\0'; ++p) {
        h ^= (uint64_t)(*p);
        h *= 1099511628211ULL;
    }
    return h;
}

uint64_t hash_djb2(const char *s) {
    uint64_t h = 5381ULL;
    for (const unsigned char *p = (const unsigned char *)s; *p != '\0'; ++p) {
        h = h * 33ULL + (uint64_t)(*p);
    }
    return h;
}

uint64_t hash_mix64(uint64_t x) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

void stampa_stat(const char *nome, const size_t *cont, size_t m, size_t n) {
    size_t occupati = 0;
    size_t max_carico = 0;
    for (size_t i = 0; i < m; ++i) {
        if (cont[i] > 0) {
            ++occupati;
            if (cont[i] > max_carico) {
                max_carico = cont[i];
            }
        }
    }
    size_t vuoti = m - occupati;
    size_t collisioni = n - occupati;
    printf("STAT %s: occupati=%zu vuoti=%zu collisioni=%zu max_carico=%zu\n",
           nome, occupati, vuoti, collisioni, max_carico);
}

int main(void) {
    char riga[256], modo[8], extra = '\0';
    int m_in = 0, n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%7s %d %d %c", modo, &m_in, &n_in, &extra) != 3 ||
        m_in < 1 || (size_t)m_in > MAX_SECCHI || n_in < 0 || (size_t)n_in > MAX_CHIAVI ||
        (strcmp(modo, "STR") != 0 && strcmp(modo, "INT") != 0)) {
        fprintf(stderr, "Errore: intestazione non valida.\n");
        return EXIT_FAILURE;
    }
    size_t m = (size_t)m_in;
    size_t n = (size_t)n_in;
    size_t *c1 = calloc(m, sizeof(*c1));
    size_t *c2 = calloc(m, sizeof(*c2));
    if (c1 == nullptr || c2 == nullptr) {
        free(c1);
        free(c2);
        fprintf(stderr, "Errore: memoria esaurita.\n");
        return EXIT_FAILURE;
    }
    if (strcmp(modo, "STR") == 0) {
        for (size_t i = 0; i < n; ++i) {
            char chiave[64];
            if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
                sscanf(riga, "%63s %c", chiave, &extra) != 1) {
                free(c1);
                free(c2);
                fprintf(stderr, "Errore: chiave stringa non valida.\n");
                return EXIT_FAILURE;
            }
            size_t i1 = (size_t)(hash_fnv1a(chiave) % m);
            size_t i2 = (size_t)(hash_djb2(chiave) % m);
            ++c1[i1];
            ++c2[i2];
            printf("%s: fnv1a=%zu djb2=%zu\n", chiave, i1, i2);
        }
        stampa_stat("fnv1a", c1, m, n);
        stampa_stat("djb2", c2, m, n);
    } else {
        for (size_t i = 0; i < n; ++i) {
            unsigned long long val = 0;
            if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
                sscanf(riga, "%llu %c", &val, &extra) != 1) {
                free(c1);
                free(c2);
                fprintf(stderr, "Errore: chiave intera non valida.\n");
                return EXIT_FAILURE;
            }
            uint64_t x = (uint64_t)val;
            size_t i1 = (size_t)(x % m);
            size_t i2 = (size_t)(hash_mix64(x) % m);
            ++c1[i1];
            ++c2[i2];
            printf("%" PRIu64 ": identita=%zu mix64=%zu\n", x, i1, i2);
        }
        stampa_stat("identita", c1, m, n);
        stampa_stat("mix64", c2, m, n);
    }
    free(c1);
    free(c2);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_CAP = 64;

typedef struct nodo_freq {
    char *chiave;
    int64_t conteggio;
    struct nodo_freq *prox;
} nodo_freq_t;

typedef struct tab_freq {
    nodo_freq_t **secchi;
    size_t cap;
    size_t len;
} tab_freq_t;

uint64_t hash_fnv1a(const char *s) {
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *p = (const unsigned char *)s; *p != '\0'; ++p) {
        h ^= (uint64_t)(*p);
        h *= 1099511628211ULL;
    }
    return h;
}

bool tab_init(tab_freq_t *t, size_t cap) {
    if (t == nullptr || cap < 1 || cap > MAX_CAP) { return false; }
    t->secchi = malloc(cap * sizeof(*t->secchi));
    if (t->secchi == nullptr) {
        t->cap = 0;
        t->len = 0;
        return false;
    }
    for (size_t i = 0; i < cap; ++i) { t->secchi[i] = nullptr; }
    t->cap = cap;
    t->len = 0;
    return true;
}

const nodo_freq_t *tab_cerca(const tab_freq_t *t, const char *chiave) {
    size_t idx = (size_t)(hash_fnv1a(chiave) % t->cap);
    for (const nodo_freq_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (strcmp(c->chiave, chiave) == 0) { return c; }
    }
    return nullptr;
}

int tab_aggiungi(tab_freq_t *t, const char *chiave, int64_t delta,
                 size_t *secchio_out, int64_t *val_out) {
    size_t idx = (size_t)(hash_fnv1a(chiave) % t->cap);
    *secchio_out = idx;
    for (nodo_freq_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (strcmp(c->chiave, chiave) == 0) {
            c->conteggio += delta;
            *val_out = c->conteggio;
            return 0;
        }
    }
    nodo_freq_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return -1; }
    n->chiave = strdup(chiave);
    if (n->chiave == nullptr) {
        free(n);
        return -1;
    }
    n->conteggio = delta;
    n->prox = t->secchi[idx];
    t->secchi[idx] = n;
    ++t->len;
    *val_out = n->conteggio;
    return 1;
}

bool tab_rimuovi(tab_freq_t *t, const char *chiave) {
    size_t idx = (size_t)(hash_fnv1a(chiave) % t->cap);
    nodo_freq_t **cur = &t->secchi[idx];
    while (*cur != nullptr && strcmp((*cur)->chiave, chiave) != 0) {
        cur = &(*cur)->prox;
    }
    if (*cur == nullptr) { return false; }
    nodo_freq_t *da_lib = *cur;
    *cur = da_lib->prox;
    free(da_lib->chiave);
    free(da_lib);
    --t->len;
    return true;
}

void tab_distruggi(tab_freq_t *t) {
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_freq_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_freq_t *prossimo = c->prox;
            free(c->chiave);
            free(c);
            c = prossimo;
        }
    }
    free(t->secchi);
    t->secchi = nullptr;
    t->cap = 0;
    t->len = 0;
}

void tab_dump(const tab_freq_t *t) {
    printf("Tabella (len=%zu, cap=%zu):\n", t->len, t->cap);
    if (t->len == 0) {
        printf("  (vuota)\n");
        return;
    }
    for (size_t i = 0; i < t->cap; ++i) {
        if (t->secchi[i] == nullptr) { continue; }
        printf("  [%zu]:", i);
        for (const nodo_freq_t *c = t->secchi[i]; c != nullptr; c = c->prox) {
            printf("%s%s=%" PRId64, (c == t->secchi[i]) ? " " : " -> ", c->chiave, c->conteggio);
        }
        printf("\n");
    }
}

int main(void) {
    char riga[256], cmd[16], parola[48], extra = '\0';
    int cap_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &cap_in, &extra) != 1 || cap_in < 1 || (size_t)cap_in > MAX_CAP) {
        fprintf(stderr, "Errore: capacità iniziale non valida.\n");
        return EXIT_FAILURE;
    }
    tab_freq_t tab = {};
    if (!tab_init(&tab, (size_t)cap_in)) { return EXIT_FAILURE; }
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long delta = 0;
        if (strcmp(cmd, "INC") == 0 && sscanf(riga, "INC %47s %lld %c", parola, &delta, &extra) == 2 && delta > 0) {
            size_t secchio = 0;
            int64_t val = 0;
            int r = tab_aggiungi(&tab, parola, (int64_t)delta, &secchio, &val);
            if (r == -1) { tab_distruggi(&tab); return EXIT_FAILURE; }
            printf("%s %s=%" PRId64 " (secchio=%zu)\n", (r == 1) ? "INS" : "UPD", parola, val, secchio);
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %47s %c", parola, &extra) == 1) {
            const nodo_freq_t *n = tab_cerca(&tab, parola);
            if (n != nullptr) { printf("GET %s: %" PRId64 "\n", parola, n->conteggio); }
            else { printf("GET %s: NON TROVATO\n", parola); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %47s %c", parola, &extra) == 1) {
            printf("DEL %s: %s\n", parola, tab_rimuovi(&tab, parola) ? "OK" : "NON TROVATO");
        } else if (strcmp(cmd, "DUMP") == 0 && sscanf(riga, "DUMP %c", &extra) != 1) {
            tab_dump(&tab);
        } else {
            tab_distruggi(&tab);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    tab_distruggi(&tab);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_CAP_INIT = 16;
constexpr size_t MAX_CAP_TAB = 1024;

typedef struct nodo_cfg {
    char *chiave;
    uint64_t hash;
    int32_t valore;
    struct nodo_cfg *prox;
} nodo_cfg_t;

typedef struct tab_cfg {
    nodo_cfg_t **secchi;
    size_t cap;
    size_t len;
    size_t num_rehash;
    size_t nodi_allocati;
} tab_cfg_t;

uint64_t hash_fnv1a(const char *s) {
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *p = (const unsigned char *)s; *p != '\0'; ++p) {
        h ^= (uint64_t)(*p);
        h *= 1099511628211ULL;
    }
    return h;
}

bool tab_init(tab_cfg_t *t, size_t cap) {
    if (t == nullptr || cap < 1 || cap > MAX_CAP_INIT) { return false; }
    t->secchi = malloc(cap * sizeof(*t->secchi));
    if (t->secchi == nullptr) { return false; }
    for (size_t i = 0; i < cap; ++i) { t->secchi[i] = nullptr; }
    t->cap = cap;
    t->len = 0;
    t->num_rehash = 0;
    t->nodi_allocati = 0;
    return true;
}

bool tab_ridimensiona(tab_cfg_t *t, size_t nuova_cap, size_t *spostati_out) {
    if (t == nullptr || nuova_cap < 1 || nuova_cap > MAX_CAP_TAB ||
        nuova_cap > SIZE_MAX / sizeof(*t->secchi)) { return false; }
    nodo_cfg_t **nuovi = malloc(nuova_cap * sizeof(*nuovi));
    if (nuovi == nullptr) { return false; }
    for (size_t i = 0; i < nuova_cap; ++i) { nuovi[i] = nullptr; }
    size_t spostati = 0;
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_cfg_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_cfg_t *prossimo = c->prox;
            size_t idx = (size_t)(c->hash % nuova_cap);
            c->prox = nuovi[idx];
            nuovi[idx] = c;
            ++spostati;
            c = prossimo;
        }
    }
    free(t->secchi);
    t->secchi = nuovi;
    t->cap = nuova_cap;
    ++t->num_rehash;
    if (spostati_out != nullptr) { *spostati_out = spostati; }
    return true;
}

const nodo_cfg_t *tab_cerca(const tab_cfg_t *t, const char *chiave) {
    uint64_t h = hash_fnv1a(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (const nodo_cfg_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && strcmp(c->chiave, chiave) == 0) { return c; }
    }
    return nullptr;
}

int tab_put(tab_cfg_t *t, const char *chiave, int32_t val,
            bool *rehash_fatto, size_t *vecchia_cap, size_t *spostati) {
    *rehash_fatto = false;
    uint64_t h = hash_fnv1a(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (nodo_cfg_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && strcmp(c->chiave, chiave) == 0) {
            c->valore = val;
            return 0;
        }
    }
    if ((t->len + 1) * 4 > t->cap * 3) {
        *vecchia_cap = t->cap;
        if (!tab_ridimensiona(t, t->cap * 2, spostati)) { return -1; }
        *rehash_fatto = true;
        idx = (size_t)(h % t->cap);
    }
    nodo_cfg_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return -1; }
    n->chiave = strdup(chiave);
    if (n->chiave == nullptr) { free(n); return -1; }
    n->hash = h;
    n->valore = val;
    n->prox = t->secchi[idx];
    t->secchi[idx] = n;
    ++t->len;
    ++t->nodi_allocati;
    return 1;
}

bool tab_rimuovi(tab_cfg_t *t, const char *chiave) {
    uint64_t h = hash_fnv1a(chiave);
    size_t idx = (size_t)(h % t->cap);
    nodo_cfg_t **cur = &t->secchi[idx];
    while (*cur != nullptr && ((*cur)->hash != h || strcmp((*cur)->chiave, chiave) != 0)) {
        cur = &(*cur)->prox;
    }
    if (*cur == nullptr) { return false; }
    nodo_cfg_t *da_lib = *cur;
    *cur = da_lib->prox;
    free(da_lib->chiave);
    free(da_lib);
    --t->len;
    return true;
}

size_t tab_max_catena(const tab_cfg_t *t) {
    size_t max_c = 0;
    for (size_t i = 0; i < t->cap; ++i) {
        size_t lung = 0;
        for (const nodo_cfg_t *c = t->secchi[i]; c != nullptr; c = c->prox) { ++lung; }
        if (lung > max_c) { max_c = lung; }
    }
    return max_c;
}

void tab_distruggi(tab_cfg_t *t) {
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_cfg_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_cfg_t *p = c->prox;
            free(c->chiave);
            free(c);
            c = p;
        }
    }
    free(t->secchi);
    *t = (tab_cfg_t){};
}

int main(void) {
    char riga[256], cmd[16], chiave[48], extra = '\0';
    int cap_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &cap_in, &extra) != 1 || cap_in < 1 || (size_t)cap_in > MAX_CAP_INIT) {
        fprintf(stderr, "Errore: capacità iniziale non valida.\n");
        return EXIT_FAILURE;
    }
    tab_cfg_t tab = {};
    if (!tab_init(&tab, (size_t)cap_in)) { return EXIT_FAILURE; }
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long v = 0;
        size_t target = 0;
        if (strcmp(cmd, "PUT") == 0 && sscanf(riga, "PUT %47s %lld %c", chiave, &v, &extra) == 2 &&
            v >= INT32_MIN && v <= INT32_MAX) {
            bool rh = false; size_t old_cap = 0, sp = 0;
            int r = tab_put(&tab, chiave, (int32_t)v, &rh, &old_cap, &sp);
            if (r == -1) { tab_distruggi(&tab); return EXIT_FAILURE; }
            if (rh) { printf("REHASH %zu -> %zu (spostati=%zu)\n", old_cap, tab.cap, sp); }
            printf("%s %s=%" PRId32 "\n", (r == 1) ? "INS" : "UPD", chiave, (int32_t)v);
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %47s %c", chiave, &extra) == 1) {
            const nodo_cfg_t *n = tab_cerca(&tab, chiave);
            if (n != nullptr) { printf("GET %s: %" PRId32 "\n", chiave, n->valore); }
            else { printf("GET %s: NON TROVATO\n", chiave); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %47s %c", chiave, &extra) == 1) {
            printf("DEL %s: %s\n", chiave, tab_rimuovi(&tab, chiave) ? "OK" : "NON TROVATO");
        } else if (strcmp(cmd, "RESERVE") == 0 && sscanf(riga, "RESERVE %zu %c", &target, &extra) == 1) {
            if (target < 1 || target > MAX_CAP_TAB) { printf("RESERVE RIFIUTATO\n"); }
            else if (target <= tab.cap) { printf("RESERVE NOOP (cap=%zu)\n", tab.cap); }
            else {
                size_t old_cap = tab.cap, sp = 0;
                if (!tab_ridimensiona(&tab, target, &sp)) { printf("RESERVE RIFIUTATO\n"); }
                else { printf("REHASH %zu -> %zu (spostati=%zu)\n", old_cap, tab.cap, sp); }
            }
        } else if (strcmp(cmd, "STAT") == 0 && sscanf(riga, "STAT %c", &extra) != 1) {
            double carico = (double)tab.len / (double)tab.cap;
            printf("STAT len=%zu cap=%zu carico=%.2f max_catena=%zu rehash=%zu alloc_nodi=%zu\n",
                   tab.len, tab.cap, carico, tab_max_catena(&tab), tab.num_rehash, tab.nodi_allocati);
        } else {
            tab_distruggi(&tab); return EXIT_FAILURE;
        }
    }
    tab_distruggi(&tab);
    return EXIT_SUCCESS;
}

#include <ctype.h>
#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_POOL = 32;

typedef uint64_t (*hash_fn)(const void *chiave);
typedef bool (*uguali_fn)(const void *a, const void *b);
typedef void (*visita_fn)(const void *chiave, void *valore, void *ctx);

typedef struct nodo_ht {
    void *chiave;
    void *valore;
    uint64_t hash;
    struct nodo_ht *prox;
} nodo_ht_t;

typedef struct tab_ht {
    nodo_ht_t **secchi;
    size_t cap;
    size_t len;
    hash_fn hash;
    uguali_fn uguali;
} tab_ht_t;

typedef struct chiave_cella { uint8_t piano; int32_t stanza; } chiave_cella_t;
typedef struct ctx_calde { double soglia; size_t conteggio; double somma; } ctx_calde_t;

bool ht_init(tab_ht_t *t, size_t cap, hash_fn h, uguali_fn u) {
    t->secchi = malloc(cap * sizeof(*t->secchi));
    if (t->secchi == nullptr) { return false; }
    for (size_t i = 0; i < cap; ++i) { t->secchi[i] = nullptr; }
    t->cap = cap; t->len = 0; t->hash = h; t->uguali = u;
    return true;
}

bool ht_ridimensiona(tab_ht_t *t, size_t nuova_cap) {
    if (nuova_cap == 0 || nuova_cap > SIZE_MAX / sizeof(*t->secchi)) { return false; }
    nodo_ht_t **nuovi = malloc(nuova_cap * sizeof(*nuovi));
    if (nuovi == nullptr) { return false; }
    for (size_t i = 0; i < nuova_cap; ++i) { nuovi[i] = nullptr; }
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_ht_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_ht_t *p = c->prox;
            size_t idx = (size_t)(c->hash % nuova_cap);
            c->prox = nuovi[idx];
            nuovi[idx] = c;
            c = p;
        }
    }
    free(t->secchi);
    t->secchi = nuovi;
    t->cap = nuova_cap;
    return true;
}

int ht_inserisci(tab_ht_t *t, void *chiave, void *valore) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (nodo_ht_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && t->uguali(c->chiave, chiave)) { c->valore = valore; return 0; }
    }
    if ((t->len + 1) * 4 > t->cap * 3) {
        if (!ht_ridimensiona(t, t->cap * 2)) { return -1; }
        idx = (size_t)(h % t->cap);
    }
    nodo_ht_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return -1; }
    *n = (nodo_ht_t){.chiave = chiave, .valore = valore, .hash = h, .prox = t->secchi[idx]};
    t->secchi[idx] = n;
    ++t->len;
    return 1;
}

void *ht_cerca(const tab_ht_t *t, const void *chiave) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (const nodo_ht_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && t->uguali(c->chiave, chiave)) { return c->valore; }
    }
    return nullptr;
}

bool ht_rimuovi(tab_ht_t *t, const void *chiave) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    nodo_ht_t **cur = &t->secchi[idx];
    while (*cur != nullptr && ((*cur)->hash != h || !t->uguali((*cur)->chiave, chiave))) {
        cur = &(*cur)->prox;
    }
    if (*cur == nullptr) { return false; }
    nodo_ht_t *d = *cur; *cur = d->prox; free(d); --t->len;
    return true;
}

void ht_visita(const tab_ht_t *t, visita_fn fn, void *ctx) {
    for (size_t i = 0; i < t->cap; ++i) {
        for (const nodo_ht_t *c = t->secchi[i]; c != nullptr; c = c->prox) { fn(c->chiave, c->valore, ctx); }
    }
}

void ht_distruggi(tab_ht_t *t) {
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_ht_t *c = t->secchi[i];
        while (c != nullptr) { nodo_ht_t *p = c->prox; free(c); c = p; }
    }
    free(t->secchi); *t = (tab_ht_t){};
}

uint64_t hash_str_ci(const void *p) {
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *s = p; *s != '\0'; ++s) {
        h ^= (uint64_t)(unsigned char)tolower(*s);
        h *= 1099511628211ULL;
    }
    return h;
}

bool uguali_str_ci(const void *a, const void *b) {
    const unsigned char *sa = a, *sb = b;
    while (*sa != '\0' && *sb != '\0') {
        if (tolower(*sa) != tolower(*sb)) { return false; }
        ++sa; ++sb;
    }
    return *sa == *sb;
}

uint64_t hash_cella(const void *p) {
    const chiave_cella_t *c = p;
    uint64_t h = 14695981039346656037ULL;
    h ^= (uint64_t)c->piano; h *= 1099511628211ULL;
    uint32_t st = (uint32_t)c->stanza;
    for (unsigned int sh = 0; sh < 32; sh += 8) {
        h ^= (uint64_t)((st >> sh) & 0xffU); h *= 1099511628211ULL;
    }
    return h;
}

bool uguali_cella(const void *a, const void *b) {
    const chiave_cella_t *ca = a, *cb = b;
    return ca->piano == cb->piano && ca->stanza == cb->stanza;
}

void visita_somma_str(const void *k, void *v, void *ctx) {
    (void)k; *(int64_t *)ctx += *(const int32_t *)v;
}

void visita_calde(const void *k, void *v, void *ctx) {
    (void)k; ctx_calde_t *c = ctx; double t = *(const double *)v;
    if (t >= c->soglia) { ++c->conteggio; c->somma += t; }
}

int main(void) {
    tab_ht_t ht_str = {}, ht_celle = {};
    if (!ht_init(&ht_str, 4, hash_str_ci, uguali_str_ci) ||
        !ht_init(&ht_celle, 4, hash_cella, uguali_cella)) {
        ht_distruggi(&ht_str); ht_distruggi(&ht_celle); return EXIT_FAILURE;
    }
    char pool_ks[MAX_POOL][24] = {}; int32_t pool_vs[MAX_POOL] = {}; size_t ns = 0;
    chiave_cella_t pool_kc[MAX_POOL]; double pool_vc[MAX_POOL] = {}; size_t nc = 0;
    char riga[256], cmd[16], kbuf[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long vi = 0, st = 0; unsigned int pi = 0; double td = 0.0;
        if (strcmp(cmd, "S_PUT") == 0 && sscanf(riga, "S_PUT %23s %lld %c", kbuf, &vi, &extra) == 2 && ns < MAX_POOL) {
            int i = 0; while (kbuf[i] != '\0') { pool_ks[ns][i] = kbuf[i]; ++i; } pool_ks[ns][i] = '\0';
            pool_vs[ns] = (int32_t)vi;
            int r = ht_inserisci(&ht_str, pool_ks[ns], &pool_vs[ns]); ++ns;
            printf("%s %s=%" PRId32 "\n", (r == 1) ? "S_INS" : "S_UPD", kbuf, (int32_t)vi);
        } else if (strcmp(cmd, "S_GET") == 0 && sscanf(riga, "S_GET %23s %c", kbuf, &extra) == 1) {
            const int32_t *v = ht_cerca(&ht_str, kbuf);
            if (v != nullptr) { printf("S_GET %s: %" PRId32 "\n", kbuf, *v); }
            else { printf("S_GET %s: NON TROVATO\n", kbuf); }
        } else if (strcmp(cmd, "S_DEL") == 0 && sscanf(riga, "S_DEL %23s %c", kbuf, &extra) == 1) {
            printf("S_DEL %s: %s\n", kbuf, ht_rimuovi(&ht_str, kbuf) ? "OK" : "NON TROVATO");
        } else if (strcmp(cmd, "C_PUT") == 0 && sscanf(riga, "C_PUT %u %lld %lf %c", &pi, &st, &td, &extra) == 3 && pi <= UINT8_MAX && nc < MAX_POOL) {
            memset(&pool_kc[nc], 0x55, sizeof(pool_kc[nc]));
            pool_kc[nc].piano = (uint8_t)pi; pool_kc[nc].stanza = (int32_t)st; pool_vc[nc] = td;
            int r = ht_inserisci(&ht_celle, &pool_kc[nc], &pool_vc[nc]); ++nc;
            printf("%s (%u,%" PRId32 ")=%.1f\n", (r == 1) ? "C_INS" : "C_UPD", pi, (int32_t)st, td);
        } else if (strcmp(cmd, "C_GET") == 0 && sscanf(riga, "C_GET %u %lld %c", &pi, &st, &extra) == 2 && pi <= UINT8_MAX) {
            chiave_cella_t kc; memset(&kc, 0xAA, sizeof(kc)); kc.piano = (uint8_t)pi; kc.stanza = (int32_t)st;
            const double *v = ht_cerca(&ht_celle, &kc);
            if (v != nullptr) { printf("C_GET (%u,%" PRId32 "): %.1f\n", pi, (int32_t)st, *v); }
            else { printf("C_GET (%u,%" PRId32 "): NON TROVATO\n", pi, (int32_t)st); }
        } else if (strcmp(cmd, "C_DEL") == 0 && sscanf(riga, "C_DEL %u %lld %c", &pi, &st, &extra) == 2 && pi <= UINT8_MAX) {
            chiave_cella_t kc; memset(&kc, 0xAA, sizeof(kc)); kc.piano = (uint8_t)pi; kc.stanza = (int32_t)st;
            printf("C_DEL (%u,%" PRId32 "): %s\n", pi, (int32_t)st, ht_rimuovi(&ht_celle, &kc) ? "OK" : "NON TROVATO");
        } else if (strcmp(cmd, "REPORT") == 0 && sscanf(riga, "REPORT %lf %c", &td, &extra) == 1) {
            int64_t somma_s = 0; ht_visita(&ht_str, visita_somma_str, &somma_s);
            ctx_calde_t cc = {.soglia = td, .conteggio = 0, .somma = 0.0}; ht_visita(&ht_celle, visita_calde, &cc);
            double media = (cc.conteggio > 0) ? (cc.somma / (double)cc.conteggio) : 0.0;
            printf("REPORT str: len=%zu somma=%" PRId64 "\n", ht_str.len, somma_s);
            printf("REPORT celle: len=%zu sopra_soglia=%zu media_sopra=%.2f\n", ht_celle.len, cc.conteggio, media);
        } else { ht_distruggi(&ht_str); ht_distruggi(&ht_celle); return EXIT_FAILURE; }
    }
    ht_distruggi(&ht_str); ht_distruggi(&ht_celle);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef uint64_t (*hash_fn)(const void *chiave);
typedef bool (*uguali_fn)(const void *a, const void *b);
typedef void (*distruggi_fn)(void *ptr);

typedef struct nodo_ht {
    void *chiave; void *valore; uint64_t hash; struct nodo_ht *prox;
} nodo_ht_t;

typedef struct tab_ht {
    nodo_ht_t **secchi; size_t cap; size_t len;
    hash_fn hash; uguali_fn uguali; distruggi_fn d_chiave; distruggi_fn d_valore;
} tab_ht_t;

typedef struct chiave_str { char *testo; size_t *cont_dist; } chiave_str_t;
typedef struct risorsa { char *etichetta; int32_t punteggio; size_t *cont_dist; } risorsa_t;

tab_ht_t *ht_crea(size_t cap, hash_fn h, uguali_fn u, distruggi_fn dc, distruggi_fn dv) {
    tab_ht_t *t = malloc(sizeof(*t));
    if (t == nullptr) { return nullptr; }
    t->secchi = malloc(cap * sizeof(*t->secchi));
    if (t->secchi == nullptr) { free(t); return nullptr; }
    for (size_t i = 0; i < cap; ++i) { t->secchi[i] = nullptr; }
    t->cap = cap; t->len = 0; t->hash = h; t->uguali = u; t->d_chiave = dc; t->d_valore = dv;
    return t;
}

bool ht_ridimensiona(tab_ht_t *t, size_t nuova_cap) {
    if (nuova_cap == 0 || nuova_cap > SIZE_MAX / sizeof(*t->secchi)) { return false; }
    nodo_ht_t **nuovi = malloc(nuova_cap * sizeof(*nuovi));
    if (nuovi == nullptr) { return false; }
    for (size_t i = 0; i < nuova_cap; ++i) { nuovi[i] = nullptr; }
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_ht_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_ht_t *p = c->prox; size_t idx = (size_t)(c->hash % nuova_cap);
            c->prox = nuovi[idx]; nuovi[idx] = c; c = p;
        }
    }
    free(t->secchi); t->secchi = nuovi; t->cap = nuova_cap;
    return true;
}

int ht_inserisci(tab_ht_t *t, void *chiave, void *valore) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (nodo_ht_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && t->uguali(c->chiave, chiave)) {
            if (t->d_valore != nullptr && c->valore != valore) { t->d_valore(c->valore); }
            c->valore = valore;
            if (t->d_chiave != nullptr && c->chiave != chiave) { t->d_chiave(chiave); }
            return 0;
        }
    }
    if ((t->len + 1) * 4 > t->cap * 3) {
        if (!ht_ridimensiona(t, t->cap * 2)) { return -1; }
        idx = (size_t)(h % t->cap);
    }
    nodo_ht_t *n = malloc(sizeof(*n));
    if (n == nullptr) { return -1; }
    *n = (nodo_ht_t){.chiave = chiave, .valore = valore, .hash = h, .prox = t->secchi[idx]};
    t->secchi[idx] = n; ++t->len;
    return 1;
}

void *ht_cerca(const tab_ht_t *t, const void *chiave) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    for (const nodo_ht_t *c = t->secchi[idx]; c != nullptr; c = c->prox) {
        if (c->hash == h && t->uguali(c->chiave, chiave)) { return c->valore; }
    }
    return nullptr;
}

bool ht_estrai(tab_ht_t *t, const void *chiave, void **val_out) {
    uint64_t h = t->hash(chiave);
    size_t idx = (size_t)(h % t->cap);
    nodo_ht_t **cur = &t->secchi[idx];
    while (*cur != nullptr && ((*cur)->hash != h || !t->uguali((*cur)->chiave, chiave))) {
        cur = &(*cur)->prox;
    }
    if (*cur == nullptr) { return false; }
    nodo_ht_t *d = *cur; *cur = d->prox;
    if (t->d_chiave != nullptr) { t->d_chiave(d->chiave); }
    if (val_out != nullptr) { *val_out = d->valore; }
    else if (t->d_valore != nullptr) { t->d_valore(d->valore); }
    free(d); --t->len;
    return true;
}

bool ht_rimuovi(tab_ht_t *t, const void *chiave) { return ht_estrai(t, chiave, nullptr); }

size_t ht_rimuovi_per_valore(tab_ht_t *t, const void *valore) {
    size_t rim = 0;
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_ht_t **cur = &t->secchi[i];
        while (*cur != nullptr) {
            if ((*cur)->valore == valore) {
                nodo_ht_t *d = *cur; *cur = d->prox;
                if (t->d_chiave != nullptr) { t->d_chiave(d->chiave); }
                if (t->d_valore != nullptr) { t->d_valore(d->valore); }
                free(d); --t->len; ++rim;
            } else { cur = &(*cur)->prox; }
        }
    }
    return rim;
}

void ht_distruggi(tab_ht_t *t) {
    if (t == nullptr) { return; }
    for (size_t i = 0; i < t->cap; ++i) {
        nodo_ht_t *c = t->secchi[i];
        while (c != nullptr) {
            nodo_ht_t *p = c->prox;
            if (t->d_chiave != nullptr) { t->d_chiave(c->chiave); }
            if (t->d_valore != nullptr) { t->d_valore(c->valore); }
            free(c); c = p;
        }
    }
    free(t->secchi); free(t);
}

uint64_t hash_kstr(const void *p) {
    const chiave_str_t *k = p; uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *s = (const unsigned char *)k->testo; *s != '\0'; ++s) {
        h ^= (uint64_t)(*s); h *= 1099511628211ULL;
    }
    return h;
}

bool uguali_kstr(const void *a, const void *b) {
    return strcmp(((const chiave_str_t *)a)->testo, ((const chiave_str_t *)b)->testo) == 0;
}

void distruggi_kstr(void *p) {
    chiave_str_t *k = p; if (k == nullptr) { return; }
    if (k->cont_dist != nullptr) { ++(*k->cont_dist); }
    free(k->testo); free(k);
}

chiave_str_t *crea_kstr(const char *s, size_t *c_cre, size_t *c_dis) {
    chiave_str_t *k = malloc(sizeof(*k));
    if (k == nullptr) { return nullptr; }
    k->testo = strdup(s); if (k->testo == nullptr) { free(k); return nullptr; }
    k->cont_dist = c_dis; ++(*c_cre); return k;
}

void distruggi_risorsa(void *p) {
    risorsa_t *r = p; if (r == nullptr) { return; }
    if (r->cont_dist != nullptr) { ++(*r->cont_dist); }
    free(r->etichetta); free(r);
}

risorsa_t *crea_risorsa(const char *et, int32_t pt, size_t *v_cre, size_t *v_dis) {
    risorsa_t *r = malloc(sizeof(*r)); if (r == nullptr) { return nullptr; }
    r->etichetta = strdup(et); if (r->etichetta == nullptr) { free(r); return nullptr; }
    r->punteggio = pt; r->cont_dist = v_dis; ++(*v_cre); return r;
}

int main(void) {
    size_t k_cre = 0, k_dis = 0, v_cre = 0, v_dis = 0;
    tab_ht_t *tab_prop = ht_crea(4, hash_kstr, uguali_kstr, distruggi_kstr, distruggi_risorsa);
    tab_ht_t *tab_alias = ht_crea(4, hash_kstr, uguali_kstr, distruggi_kstr, nullptr);
    if (tab_prop == nullptr || tab_alias == nullptr) { ht_distruggi(tab_alias); ht_distruggi(tab_prop); return EXIT_FAILURE; }
    char riga[256], cmd[16], a[48], b[48], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long pt = 0;
        if (strcmp(cmd, "PUT") == 0 && sscanf(riga, "PUT %47s %47s %lld %c", a, b, &pt, &extra) == 3) {
            chiave_str_t kq = {.testo = a, .cont_dist = nullptr};
            void *vecchio = ht_cerca(tab_prop, &kq);
            chiave_str_t *kh = crea_kstr(a, &k_cre, &k_dis);
            risorsa_t *rh = crea_risorsa(b, (int32_t)pt, &v_cre, &v_dis);
            int esito = (kh != nullptr && rh != nullptr) ? ht_inserisci(tab_prop, kh, rh) : -1;
            if (esito == -1) { distruggi_kstr(kh); distruggi_risorsa(rh); ht_distruggi(tab_alias); ht_distruggi(tab_prop); return EXIT_FAILURE; }
            if (esito == 0) { printf("PUT %s: AGGIORNATO (alias_invalidati=%zu)\n", a, ht_rimuovi_per_valore(tab_alias, vecchio)); }
            else { printf("PUT %s: INSERITO\n", a); }
        } else if (strcmp(cmd, "ALIAS") == 0 && sscanf(riga, "ALIAS %47s %47s %c", a, b, &extra) == 2) {
            chiave_str_t kq = {.testo = b, .cont_dist = nullptr}; void *val = ht_cerca(tab_prop, &kq);
            if (val == nullptr) { printf("ALIAS %s: ASSENTE %s\n", a, b); continue; }
            chiave_str_t *ka = crea_kstr(a, &k_cre, &k_dis);
            int esito = (ka != nullptr) ? ht_inserisci(tab_alias, ka, val) : -1;
            if (esito == -1) { distruggi_kstr(ka); ht_distruggi(tab_alias); ht_distruggi(tab_prop); return EXIT_FAILURE; }
            printf("ALIAS %s -> %s: %s\n", a, b, (esito == 1) ? "INSERITO" : "AGGIORNATO");
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %47s %c", a, &extra) == 1) {
            chiave_str_t kq = {.testo = a, .cont_dist = nullptr}; const risorsa_t *r = ht_cerca(tab_prop, &kq);
            if (r != nullptr) { printf("GET %s: %s (%" PRId32 ")\n", a, r->etichetta, r->punteggio); }
            else { printf("GET %s: NON TROVATO\n", a); }
        } else if (strcmp(cmd, "GET_ALIAS") == 0 && sscanf(riga, "GET_ALIAS %47s %c", a, &extra) == 1) {
            chiave_str_t kq = {.testo = a, .cont_dist = nullptr}; const risorsa_t *r = ht_cerca(tab_alias, &kq);
            if (r != nullptr) { printf("GET_ALIAS %s: %s (%" PRId32 ")\n", a, r->etichetta, r->punteggio); }
            else { printf("GET_ALIAS %s: NON TROVATO\n", a); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %47s %c", a, &extra) == 1) {
            chiave_str_t kq = {.testo = a, .cont_dist = nullptr}; void *val = ht_cerca(tab_prop, &kq);
            if (val == nullptr) { printf("DEL %s: NON TROVATO\n", a); }
            else { size_t inv = ht_rimuovi_per_valore(tab_alias, val); ht_rimuovi(tab_prop, &kq); printf("DEL %s: OK (alias_invalidati=%zu)\n", a, inv); }
        } else if (strcmp(cmd, "EXTRACT") == 0 && sscanf(riga, "EXTRACT %47s %c", a, &extra) == 1) {
            chiave_str_t kq = {.testo = a, .cont_dist = nullptr}; void *estr = nullptr;
            if (!ht_estrai(tab_prop, &kq, &estr)) { printf("EXTRACT %s: NON TROVATO\n", a); }
            else { size_t inv = ht_rimuovi_per_valore(tab_alias, estr); risorsa_t *r = estr; printf("EXTRACT %s: %s (%" PRId32 ") (alias_invalidati=%zu)\n", a, r->etichetta, r->punteggio, inv); distruggi_risorsa(r); }
        } else if (strcmp(cmd, "BILANCIO") == 0 && sscanf(riga, "BILANCIO %c", &extra) != 1) {
            printf("BILANCIO chiavi=%zu/%zu valori=%zu/%zu\n", k_cre, k_dis, v_cre, v_dis);
        } else { ht_distruggi(tab_alias); ht_distruggi(tab_prop); return EXIT_FAILURE; }
    }
    ht_distruggi(tab_alias); ht_distruggi(tab_prop);
    printf("FINE chiavi=%zu/%zu valori=%zu/%zu\n", k_cre, k_dis, v_cre, v_dis);
    return EXIT_SUCCESS;
}
